17	// dataVersion 是快照格式的版本标记，便于将来迁移。
18	const dataVersion = 1
19	
20	// snapshot 是写入磁盘的完整状态。所有业务对象集中在一个文件中，
21	// 采用“临时文件 + 原子改名”整体落盘：成功操作与其审计事件一同保留，
22	// 失败的操作在 mutate 中就已丢弃，不会写出半截状态。
23	type snapshot struct {
24		FormatVersion  int                       `json:"format_version"`
25		Patients       map[string]*Patient       `json:"patients"`
26		Encounters     map[string]*Encounter     `json:"encounters"`
27		Records        map[string]*Record        `json:"records"`
28		Versions       map[string]*Version       `json:"versions"`
29		Authorizations map[string]*Authorization `json:"authorizations"`
30		Exchanges      map[string]*Exchange      `json:"exchanges"`
31		AuditEvents    []*AuditEvent             `json:"audit_events"`
32	}
33	
34	// Clock 决定“发生时间”的来源。生产使用实时时钟；测试可注入固定/可控时钟
35	// 以验证开始、到期、撤回等时间边界。
36	type Clock func() time.Time
37	
38	// Store 是本地临床档案的句柄。数据存放位置由调用方在 Open 时指定。
39	// 同一目录同一时刻只允许一个 Store 打开（通过锁文件互斥）。
40	type Store struct {
41		dir   string
42		clock Clock
43		mu    sync.Mutex
44		lock  *os.File
45		data  *snapshot
46	}
47	
48	// Option 配置 Open 的行为。
49	type Option func(*Store)
50	
51	// WithClock 注入自定义时钟。
52	func WithClock(c Clock) Option {
53		return func(s *Store) { s.clock = c }
54	}
55	
56	// Open 在指定目录打开（必要时创建）本地存储。
57	// 调用方指定数据存放位置；关闭后从同一位置重新打开可看到全部历史，
58	// 到期与否始终按“本次读取时间”重新计算。
59	func Open(dir string, opts ...Option) (*Store, error) {
60		if dir == "" {
61			return nil, fmt.Errorf("%w: empty data directory", ErrInvalidArgument)
62		}
63		if err := os.MkdirAll(dir, 0o755); err != nil {
64			return nil, err
65		}
66	
67		lockPath := filepath.Join(dir, ".clinical.lock")
68		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
69		if err != nil {
70			return nil, err
71		}
72		if err := tryLockFile(lockFile); err != nil {
73			lockFile.Close()
74			return nil, err
75		}
76	
77		s := &Store{dir: dir, clock: time.Now, lock: lockFile}
78		for _, opt := range opts {
79			opt(s)
80		}
81		if s.clock == nil {
82			s.clock = time.Now
83		}
84	
85		if err := s.loadLocked(); err != nil {
86			unlockFile(lockFile)
87			lockFile.Close()
88			return nil, err
89		}
90		return s, nil
91	}
92	
93	func (s *Store) loadLocked() error {
94		path := filepath.Join(s.dir, dataName)
95		raw, err := os.ReadFile(path)
96		if os.IsNotExist(err) {
97			s.data = newSnapshot()
98			return nil
99		}
100		if err != nil {
101			return err
102		}
103		var snap snapshot
104		if err := json.Unmarshal(raw, &snap); err != nil {
105			return err
106		}
107		if snap.FormatVersion != dataVersion {
108			return fmt.Errorf("clinical: unsupported data format version %d", snap.FormatVersion)
109		}
110		ensureMaps(&snap)
111		s.data = &snap
112		return nil
113	}
114	
115	func newSnapshot() *snapshot {
116		snap := &snapshot{FormatVersion: dataVersion}
117		ensureMaps(snap)
118		return snap
119	}
120	
121	func ensureMaps(snap *snapshot) {
122		if snap.Patients == nil {
123			snap.Patients = map[string]*Patient{}
124		}
125		if snap.Encounters == nil {
126			snap.Encounters = map[string]*Encounter{}
127		}
128		if snap.Records == nil {
129			snap.Records = map[string]*Record{}
130		}
131		if snap.Versions == nil {
132			snap.Versions = map[string]*Version{}
133		}
134		if snap.Authorizations == nil {
135			snap.Authorizations = map[string]*Authorization{}
136		}
137		if snap.Exchanges == nil {
138			snap.Exchanges = map[string]*Exchange{}
139		}
140	}
141	
142	// Close 刷新并释放数据目录。Close 后任何业务方法返回 ErrClosed。
143	func (s *Store) Close() error {
144		s.mu.Lock()
145		defer s.mu.Unlock()
146		if s.lock == nil {
147			return ErrClosed
148		}
149		unlockFile(s.lock)
150		err := s.lock.Close()
151		if rmErr := os.Remove(filepath.Join(s.dir, ".clinical.lock")); rmErr != nil && !os.IsNotExist(rmErr) && err == nil {
152			err = rmErr
153		}
154		s.lock = nil
155		s.data = nil
156		return err
157	}
158	
159	func (s *Store) now() time.Time { return s.clock().UTC() }
160	
161	// mutate 在状态的深拷贝上执行业务变更。fn 返回错误时，拷贝连同其中的
162	// 半成品一并丢弃，磁盘与既有业务状态保持原样；fn 返回 nil 时整体原子落盘。
163	// 这样“引用不存在的对象/跨患者混用”等失败都不会留下半条记录。
164	func (s *Store) mutate(fn func(*snapshot) error) error {
165		s.mu.Lock()
166		defer s.mu.Unlock()
167		if s.data == nil {
168			return ErrClosed
169		}
170	
171		clone := cloneSnapshot(s.data)
172		if err := fn(clone); err != nil {
173			return err
174		}
175		if err := s.persist(clone); err != nil {
176			return err
177		}
178		s.data = clone
179		return nil
180	}
181	
182	// view 在只读快照上执行查询。
183	func (s *Store) view(fn func(*snapshot) error) error {
184		s.mu.Lock()
185		defer s.mu.Unlock()
186		if s.data == nil {
187			return ErrClosed
188		}
189		return fn(s.data)
190	}
191	
192	func (s *Store) persist(snap *snapshot) error {
193		raw, err := json.MarshalIndent(snap, "", "  ")
194		if err != nil {
195			return err
196		}
197		final := filepath.Join(s.dir, dataName)
198		tmp := filepath.Join(s.dir, dataName+".tmp")
199		if err := os.WriteFile(tmp, raw, 0o600); err != nil {
200			return err
201		}
202		if err := os.Rename(tmp, final); err != nil {
203			_ = os.Remove(tmp)
204			return err
205		}
206		return nil
207	}
208	
209	func cloneSnapshot(in *snapshot) *snapshot {
210		out := &snapshot{
211			FormatVersion:  in.FormatVersion,
212			Patients:       make(map[string]*Patient, len(in.Patients)),
213			Encounters:     make(map[string]*Encounter, len(in.Encounters)),
214			Records:        make(map[string]*Record, len(in.Records)),
215			Versions:       make(map[string]*Version, len(in.Versions)),
216			Authorizations: make(map[string]*Authorization, len(in.Authorizations)),
217			Exchanges:      make(map[string]*Exchange, len(in.Exchanges)),
218			AuditEvents:    make([]*AuditEvent, 0, len(in.AuditEvents)),
219		}
220		for k, v := range in.Patients {
221			p := *v
222			out.Patients[k] = &p
223		}
224		for k, v := range in.Encounters {
225			e := *v
226			out.Encounters[k] = &e
227		}
228		for k, v := range in.Records {
229			r := *v
230			r.Versions = append([]ID(nil), v.Versions...)
231			out.Records[k] = &r
232		}
233		for k, v := range in.Versions {
234			vv := *v
235			out.Versions[k] = &vv
236		}
237		for k, v := range in.Authorizations {
238			a := *v
239			a.Scopes = append([]Scope(nil), v.Scopes...)
240			a.Selections = append([]RecordSelection(nil), v.Selections...)
241			if v.RevokedAt != nil {
242				t := *v.RevokedAt
243				a.RevokedAt = &t
244			}
245			out.Authorizations[k] = &a
246		}
247		for k, x := range in.Exchanges {
248			y := *x
249			y.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
250			if x.Receipt != nil {
251				r := *x.Receipt
252				y.Receipt = &r
253			}
254			out.Exchanges[k] = &y
255		}
256		for _, ev := range in.AuditEvents {
257			e := *ev
258			out.AuditEvents = append(out.AuditEvents, &e)
259		}
260		return out
261	}
262	
263	func newID(prefix string) string {
264		var b [12]byte
265		if _, err := rand.Read(b[:]); err != nil {
266			// crypto/rand 失败在正常运行环境中不应发生；无法安全生成标识时直接中断。
267			panic(fmt.Errorf("clinical: cannot generate id: %w", err))
268		}
269		return prefix + "_" + hex.EncodeToString(b[:])
270	}
271	
272	func (s *Store) addAudit(snap *snapshot, patientID ID, actor Actor, action, objectType, objectID ID, at time.Time) {
273		snap.AuditEvents = append(snap.AuditEvents, &AuditEvent{
274			ID:         newID("aud"),
275			PatientID:  patientID,
276			ActorID:    actor.ID,
277			Action:     action,
278			ObjectType: objectType,
279			ObjectID:   objectID,
280			OccurredAt: at,
281		})
282	}
